import React from 'react';
import { Navigate, Outlet, useLocation, Link } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import { ShieldAlert } from 'lucide-react';

export default function ProtectedRoute({ allowedRoles, redirectPath = '/login', children }) {
  const { user, isAuthenticated, loading, isAdmin } = useAuth();
  const location = useLocation();

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-slate-50 dark:bg-slate-900" style={{ backgroundColor: 'var(--bg, #f8fafc)' }}>
        <div className="flex flex-col items-center gap-3">
          <div className="w-10 h-10 border-4 border-emerald-600 border-t-transparent rounded-full animate-spin" />
          <p className="text-sm font-medium text-slate-500" style={{ color: 'var(--text-secondary, #64748b)' }}>
            Oturum doğrulanıyor...
          </p>
        </div>
      </div>
    );
  }

  if (!isAuthenticated || !user) {
    return <Navigate to={redirectPath} state={{ from: location }} replace />;
  }

  // Admin kullanıcı her sayfaya ve tüm yetkilere tam erişime sahiptir
  if (allowedRoles && allowedRoles.length > 0) {
    const hasRole = isAdmin || allowedRoles.includes(user.role);
    if (!hasRole) {
      return (
        <div className="min-h-[60vh] flex flex-col items-center justify-center p-6 text-center">
          <div className="w-16 h-16 rounded-full bg-red-50 text-red-600 flex items-center justify-center mb-4">
            <ShieldAlert className="w-8 h-8" />
          </div>
          <h2 className="text-2xl font-black text-slate-900 mb-2">Erişim İzniniz Yok</h2>
          <p className="text-sm text-slate-500 max-w-md mb-6">
            Bu sayfaya erişmek için gerekli yetkiye ({allowedRoles.join(', ')}) sahip değilsiniz.
          </p>
          <Link
            to="/dashboard"
            className="px-5 py-2.5 bg-emerald-600 text-white rounded-xl text-sm font-bold hover:bg-emerald-700 transition-colors shadow-lg shadow-emerald-600/20"
          >
            Panele Dön
          </Link>
        </div>
      );
    }
  }

  return children ? children : <Outlet />;
}
