import axios from 'axios';

const API_URL = process.env.REACT_APP_API_URL || '/api';

const api = axios.create({ baseURL: API_URL, headers: { 'Content-Type': 'application/json' } });

let isRefreshing = false;
let failedQueue = [];

const processQueue = (error, token = null) => {
  failedQueue.forEach(prom => {
    if (error) {
      prom.reject(error);
    } else {
      prom.resolve(token);
    }
  });
  failedQueue = [];
};

api.interceptors.request.use(config => {
  let token = localStorage.getItem('token');
  if (!token && typeof sessionStorage !== 'undefined') {
    token = sessionStorage.getItem('token');
  }
  if (token) config.headers.Authorization = `Bearer ${token}`;
  return config;
});

api.interceptors.response.use(
  res => res,
  async err => {
    const originalRequest = err.config;
    if (!originalRequest) return Promise.reject(err);

    // Auth endpointleri için (login, register, şifre sıfırlama, refresh) otomatik yenileme tetikleme
    const url = originalRequest.url || '';
    const isAuthEndpoint = 
      url.includes('/auth/login') || 
      url.includes('/auth/register') || 
      url.includes('/auth/forgot-password') || 
      url.includes('/auth/reset-password') ||
      url.includes('/auth/refresh-token') ||
      url.includes('/auth/password'); // Şifre değiştirme hata 400 döner ama emniyet amaçlı

    if (err.response?.status === 401 && !isAuthEndpoint) {
      let currentToken = localStorage.getItem('token');
      let isFromLocalStorage = true;
      if (!currentToken && typeof sessionStorage !== 'undefined') {
        currentToken = sessionStorage.getItem('token');
        isFromLocalStorage = false;
      }

      // Eğer hiç token yoksa doğrudan oturumu sonlandır
      if (!currentToken) {
        window.dispatchEvent(new CustomEvent('auth:logout'));
        return Promise.reject(err);
      }

      // Eğer bu istek zaten yenileme sonrası tekrarlandıysa ve yine 401 aldıysa çıkış yap
      if (originalRequest._retry) {
        localStorage.removeItem('token');
        localStorage.removeItem('user');
        if (typeof sessionStorage !== 'undefined') {
          sessionStorage.removeItem('token');
          sessionStorage.removeItem('user');
        }
        window.dispatchEvent(new CustomEvent('auth:logout'));
        return Promise.reject(err);
      }

      // Eğer zaten bir yenileme işlemi devam ediyorsa kuyruğa al
      if (isRefreshing) {
        return new Promise((resolve, reject) => {
          failedQueue.push({ resolve, reject });
        })
          .then(token => {
            originalRequest.headers['Authorization'] = `Bearer ${token}`;
            return api(originalRequest);
          })
          .catch(queueErr => Promise.reject(queueErr));
      }

      originalRequest._retry = true;
      isRefreshing = true;

      try {
        const refreshResponse = await axios.post(`${API_URL}/auth/refresh-token`, { token: currentToken }, {
          headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${currentToken}` }
        });

        const newToken = refreshResponse.data?.token;
        const freshUser = refreshResponse.data?.user;

        if (newToken) {
          if (isFromLocalStorage) {
            localStorage.setItem('token', newToken);
            if (freshUser) localStorage.setItem('user', JSON.stringify(freshUser));
          } else if (typeof sessionStorage !== 'undefined') {
            sessionStorage.setItem('token', newToken);
            if (freshUser) sessionStorage.setItem('user', JSON.stringify(freshUser));
          }

          api.defaults.headers.common['Authorization'] = `Bearer ${newToken}`;
          originalRequest.headers['Authorization'] = `Bearer ${newToken}`;

          processQueue(null, newToken);
          return api(originalRequest);
        } else {
          throw new Error('Yenilenen token bulunamadı');
        }
      } catch (refreshErr) {
        processQueue(refreshErr, null);
        localStorage.removeItem('token');
        localStorage.removeItem('user');
        if (typeof sessionStorage !== 'undefined') {
          sessionStorage.removeItem('token');
          sessionStorage.removeItem('user');
        }
        window.dispatchEvent(new CustomEvent('auth:logout'));
        return Promise.reject(refreshErr);
      } finally {
        isRefreshing = false;
      }
    }

    return Promise.reject(err);
  }
);

export const authService = {
  login: (email, password) => api.post('/auth/login', { email, password }),
  demo: () => api.post('/auth/demo'),
  register: (data) => api.post('/auth/register', data),
  refreshToken: (token) => api.post('/auth/refresh-token', { token }),
  logout: () => {
    try {
      api.post('/auth/logout').catch(() => {});
    } catch (_) {}
    localStorage.removeItem('token');
    localStorage.removeItem('user');
    if (typeof sessionStorage !== 'undefined') {
      sessionStorage.removeItem('token');
      sessionStorage.removeItem('user');
    }
  },
  getMe: () => api.get('/auth/me'),
  updateProfile: (data) => api.put('/auth/profile', data),
  changePassword: (currentPassword, newPassword) =>
    api.put('/auth/password', { current_password: currentPassword, new_password: newPassword }),
  getSettings: () => api.get('/auth/settings'),
  updateSettings: (settings) => api.put('/auth/settings', settings),
  updateFarm: (data) => api.put('/auth/farm', data),
  deleteAccount: () => api.delete('/auth/account'),
  forgotPassword: (email) => api.post('/auth/forgot-password', { email }),
  resetPassword: (token, newPassword) =>
    api.post('/auth/reset-password', { token, new_password: newPassword }),
};

