export const inventoryService = {
  list: (farmId, filters = {}) =>
    api.get('/inventory', { params: { farm_id: farmId, ...filters } }),
  get: (id, farmId) =>
    api.get(`/inventory/${id}`, { params: { farm_id: farmId } }),
  create: (farmId, data) =>
    api.post('/inventory', { farm_id: farmId, ...data }),
  adjust: (farmId, id, data) =>
    api.post(`/inventory/${id}/adjust`, { farm_id: farmId, ...data }),
  update: (param1, param2, data = {}) => {
    // Supports both (farmId, id, data) and (id, farmId, data)
    let farmId = param1;
    let id = param2;
    let payload = data;
    if (typeof param2 === 'object' && param2 !== null && !data) {
      id = param1;
      payload = param2;
      farmId = payload.farm_id;
    }
    return api.put(`/inventory/${id}`, { farm_id: farmId, ...payload });
  },
  delete: (param1, param2) => {
    // Supports both (farmId, id) and (id, farmId)
    const farmId = param2 !== undefined ? param1 : undefined;
    const id = param2 !== undefined ? param2 : param1;
    return api.delete(`/inventory/${id}`, { params: { farm_id: farmId } });
  },
};

