import React, { useState, useEffect } from 'react';
import { Outlet, useLocation } from 'react-router-dom';
import Sidebar from './Sidebar';
import Navbar from './Navbar';
import Footer from './Footer';

export default function Layout() {
  const location = useLocation();
  // Masaüstünde varsayılan olarak açık, mobilde kapalı başlat
  const [sidebarOpen, setSidebarOpen] = useState(() => {
    if (typeof window !== 'undefined') {
      return window.innerWidth >= 1024;
    }
    return true;
  });

  // Ekran boyutu değiştiğinde masaüstüne geçilirse otomatik aç, küçülürse kapat
  useEffect(() => {
    const handleResize = () => {
      if (window.innerWidth >= 1024) {
        setSidebarOpen(true);
      } else {
        setSidebarOpen(false);
      }
    };

    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  // Sayfa yönlendirmelerinde mobilde menüyü otomatik kapat
  useEffect(() => {
    if (window.innerWidth < 1024) {
      setSidebarOpen(false);
    }
  }, [location.pathname]);

  return (
    <div 
      className="flex h-screen min-h-[100dvh] w-full overflow-hidden text-gray-900" 
      style={{ backgroundColor: 'var(--bg)' }}
    >
      {/* Yan Menü (Sidebar) */}
      <Sidebar 
        open={sidebarOpen} 
        onClose={() => setSidebarOpen(false)} 
      />

      {/* Ana İçerik Bölümü (Navbar + Sayfa İçeriği + Footer) */}
      <div className="flex-1 flex flex-col min-w-0 h-full overflow-hidden">
        {/* Üst Gezinme Çubuğu (Navbar) */}
        <Navbar onMenuClick={() => setSidebarOpen(prev => !prev)} />

        {/* Kaydırılabilir Sayfa İçeriği ve Footer */}
        <main 
          className="flex-1 flex flex-col justify-between overflow-y-auto overflow-x-hidden scrollbar-thin"
          style={{ backgroundColor: 'var(--bg)' }}
        >
          {/* Sayfa İçeriği */}
          <div className="p-3.5 sm:p-5 md:p-6 lg:p-8 flex-1 animate-fade-in w-full max-w-7xl mx-auto">
            <Outlet />
          </div>

          {/* Sayfa Altlığı (Footer) */}
          <Footer />
        </main>
      </div>
    </div>
  );
}
